draw:
var A = p.amp / 100.0;          // metres
var lam = p.lam;                // metres
var f = p.freq;                 // Hz
var k = 2 * Math.PI / lam;
var w = 2 * Math.PI * f;
var v = f * lam;

var padL = 34, padR = 14, padT = 18, padB = 26;
var Lx = 2.0;                                  // metres of rope shown
var sx = (W - padL - padR) / Lx;
var yMid = (H - padB + padT) / 2;
var sy = (H - padT - padB) / 2 / 0.055;        // metres -> px, fixed scale
var X = function (x) { return padL + x * sx; };
var Y = function (y) { return yMid - y * sy; };

ctx.lineWidth = 1;
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(padL, Y(0)); ctx.lineTo(W - padR, Y(0)); ctx.stroke();

// the rope
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 240; i++) {
  var x = Lx * i / 240;
  var y = A * Math.sin(k * x - w * t);
  if (i === 0) ctx.moveTo(X(x), Y(y)); else ctx.lineTo(X(x), Y(y));
}
ctx.stroke();

// one marked element, moving only up and down
var xm = 0.45 * Lx;
var ym = A * Math.sin(k * xm - w * t);
var vy = -w * A * Math.cos(k * xm - w * t);
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(xm), Y(A * 1.25)); ctx.lineTo(X(xm), Y(-A * 1.25)); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(xm), Y(ym), 5, 0, Math.PI * 2); ctx.fill();

// velocity arrow on that element
var arrow = vy * sy * 0.25;
if (Math.abs(arrow) > 3) {
  ctx.strokeStyle = C.figure;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(X(xm), Y(ym));
  ctx.lineTo(X(xm), Y(ym) - arrow);
  ctx.stroke();
  var s = arrow > 0 ? 1 : -1;
  ctx.beginPath();
  ctx.moveTo(X(xm), Y(ym) - arrow);
  ctx.lineTo(X(xm) - 4, Y(ym) - arrow + 6 * s);
  ctx.lineTo(X(xm) + 4, Y(ym) - arrow + 6 * s);
  ctx.closePath(); ctx.fillStyle = C.figure; ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

ctx.fillStyle = C.ink;
ctx.fillText("rope element", X(xm) + 8, padT + 10);
ctx.fillText("wave travels this way", padL + 4, H - 8);
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.2;
var ax = padL + 150, ay = H - 12;
ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(ax + 26, ay); ctx.stroke();
ctx.beginPath(); ctx.moveTo(ax + 26, ay); ctx.lineTo(ax + 20, ay - 4); ctx.lineTo(ax + 20, ay + 4);
ctx.closePath(); ctx.fillStyle = C.ink; ctx.fill();
ctx.fillText("y", 8, Y(0) - 6);
ctx.fillText("x", W - padR - 8, Y(0) + 16);

out.note = "v = f x lambda = " + v.toFixed(2) + " m/s, period T = " + (1 / f).toFixed(3)
  + " s, max transverse speed " + (w * A).toFixed(2) + " m/s";
